"""Run with two temporary PEM paths generated by test_public_tls.ps1."""
import asyncio
from pathlib import Path
import ssl
import sys

sys.path.insert(0, str(Path(__file__).resolve().parents[2]))
from remote.network import Companion
from remote.public_relay import Rooms


async def main(cert, key):
    server_tls = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
    server_tls.load_cert_chain(cert, key)
    rooms = Rooms()
    server = await asyncio.start_server(rooms.handle, '127.0.0.1', 0, ssl=server_tls)
    port = server.sockets[0].getsockname()[1]
    trusted = ssl.create_default_context(cafile=cert)
    client = Companion('localhost', port, 0, 'a' * 48, tls=True)
    client.tls_context = trusted  # Trust only this test's temporary certificate.
    task = asyncio.create_task(client.connect_forever())
    try:
        for _ in range(100):
            if client.joined:
                break
            await asyncio.sleep(0.03)
        assert client.joined, 'Companion failed real TLS admission'
        for context, name in ((ssl.create_default_context(), 'localhost'), (trusted, 'wrong.example.org')):
            try:
                _, writer = await asyncio.open_connection('127.0.0.1', port, ssl=context, server_hostname=name)
            except ssl.SSLCertVerificationError:
                pass
            else:
                writer.close()
                raise AssertionError('Invalid certificate accepted')
        print('TLS: real companion connection, untrusted certificate and wrong hostname checked')
    finally:
        task.cancel()
        try:
            await task
        except asyncio.CancelledError:
            pass
        server.close()
        await server.wait_closed()
        await rooms.close()


if __name__ == '__main__':
    asyncio.run(main(sys.argv[1], sys.argv[2]))
